116→CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)
117→RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
118→  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role)
119→$$;
