108→-- 4. Create a reusable function for generating/regenerating user inbox
109→CREATE OR REPLACE FUNCTION public.generate_user_inbox_email(p_user_id uuid)
110→  RETURNS text
111→  LANGUAGE plpgsql
112→  SECURITY DEFINER
113→  SET search_path TO 'public'
114→AS $function$
115→DECLARE
116→  raw_email text;
117→  local_part text;
118→  domain text;
119→  base_inbox text;
120→  final_inbox text;
121→  suffix text;
122→  attempts int := 0;
123→BEGIN
124→  -- Get user email from auth.users
125→  SELECT lower(trim(email)) INTO raw_email FROM auth.users WHERE id = p_user_id;
126→  IF raw_email IS NULL OR raw_email = '' THEN
127→    raw_email := 'user' || substr(md5(p_user_id::text), 1, 6);
128→  END IF;
129→
130→  -- Get inbound domain
131→  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
132→  IF domain IS NULL OR domain = '' THEN
133→    domain := 'inbound.rankora.co';
134→  END IF;
135→
136→  -- Sanitize local part
137→  local_part := split_part(raw_email, '@', 1);
138→  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
139→  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
140→  local_part := trim(both '.' from local_part);
141→  IF local_part = '' THEN local_part := 'user'; END IF;
142→
143→  base_inbox := local_part || '@' || domain;
144→  final_inbox := base_inbox;
145→
146→  -- Collision check (exclude current user)
147→  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox AND user_id != p_user_id) LOOP
148→    attempts := attempts + 1;
149→    suffix := substr(md5(random()::text), 1, 3);
150→    final_inbox := local_part || '.' || suffix || '@' || domain;
151→    IF attempts > 10 THEN
152→      final_inbox := substr(md5(p_user_id::text || now()::text), 1, 12) || '@' || domain;
153→      EXIT;
154→    END IF;
155→  END LOOP;
156→
157→  -- Update profile
158→  UPDATE public.profiles SET inbox_email = final_inbox, updated_at = now() WHERE user_id = p_user_id;
159→
160→  RETURN final_inbox;
161→END;
162→$function$;
163→
164→-- 5. Re-attach trigger for jobs (ensure it exists)
165→DROP TRIGGER IF EXISTS trg_generate_job_inbox ON public.jobs;
166→CREATE TRIGGER trg_generate_job_inbox
167→  BEFORE INSERT ON public.jobs
168→  FOR EACH ROW
169→  WHEN (NEW.inbox_email IS NULL)
170→  EXECUTE FUNCTION public.generate_job_inbox_email();
