import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

/** Extract a usable email from various formats */
function extractEmail(raw: string): string {
  // Handle "Name <email@domain>" format
  const match = raw.match(/<([^>]+)>/);
  return (match ? match[1] : raw).trim().toLowerCase();
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Helper to log and respond
  const logAndRespond = async (
    status: number,
    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
    responseBody: Record<string, unknown>
  ) => {
    try {
      await supabase.from("email_ingest_logs").insert({
        sender: logData.sender || null,
        recipient: logData.recipient || null,
        user_id: logData.user_id || null,
        job_id: logData.job_id || null,
        status: logData.status,
        error_message: logData.error_message || null,
        attachments_count: logData.attachments_count || 0,
        resumes_created: logData.resumes_created || 0,
      });
    } catch (e) {
      console.error("Failed to log email ingest:", e);
      await logSystemError({
        function_name: "email-ingest",
        error_type: "INGEST_LOG_ERROR",
        severity: "warning",
        error_message: errorToMessage(e),
        error_stack: errorToStack(e),
        user_id: logData.user_id || null,
        job_id: logData.job_id || null,
      });
    }
    return new Response(JSON.stringify(responseBody), {
      status,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  };

  try {
    // Check global email ingestion toggle
    const { data: config } = await supabase
      .from("platform_config")
      .select("email_ingestion_enabled")
      .limit(1)
      .single();

    if (config && !config.email_ingestion_enabled) {
      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
    }

    // Parse incoming payload — support Postmark JSON, legacy JSON, and multipart/form-data
    let sender: string | null = null;
    let recipient: string | null = null;
    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];

    const contentType = req.headers.get("content-type") || "";

    if (contentType.includes("application/json")) {
      const body = await req.json();

      // Postmark inbound webhook format
      if (body.FromFull || body.ToFull || body.Attachments) {
        // Postmark format
        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;

        // ToFull is an array in Postmark
        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
          recipient = body.ToFull[0].Email?.toLowerCase() || null;
        } else if (body.To) {
          recipient = extractEmail(body.To);
        }

        // Postmark attachments: array of { Name, Content (base64), ContentType, ContentLength }
        if (body.Attachments && Array.isArray(body.Attachments)) {
          for (const att of body.Attachments) {
            if (!att.Name || !att.Content) continue;
            // Only accept PDF and DOCX
            const name = att.Name.toLowerCase();
            if (!name.endsWith(".pdf") && !name.endsWith(".docx")) continue;
            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
            attachmentFiles.push({ filename: att.Name, content: fileContent });
          }
        }
      } else {
        // Legacy JSON format (backward compatible)
        sender = body.sender || null;
        recipient = body.recipient || null;

        if (body.attachments && Array.isArray(body.attachments)) {
          for (const att of body.attachments) {
            if (!att.filename || !att.content) continue;
            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
            attachmentFiles.push({ filename: att.filename, content: fileContent });
          }
        }
      }
    } else if (contentType.includes("multipart/form-data")) {
      // SendGrid/Mailgun multipart format (backward compatible)
      const formData = await req.formData();

      const envelope = formData.get("envelope") as string | null;
      const fromField = formData.get("from") as string | null;
      const toField = formData.get("to") as string | null;

      // Parse sender
      if (envelope) {
        try {
          const env = JSON.parse(envelope);
          if (env.from) sender = extractEmail(env.from);
        } catch { /* ignore */ }
      }
      if (!sender && fromField) sender = extractEmail(fromField);

      // Parse recipient
      if (envelope) {
        try {
          const env = JSON.parse(envelope);
          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
        } catch { /* ignore */ }
      }
      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);

      // Extract attachments
      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
      for (let i = 1; i <= Math.max(attachmentCount, 10); i++) {
        const file = formData.get(`attachment${i}`) as File | null;
        if (!file) continue;
        const buffer = await file.arrayBuffer();
        attachmentFiles.push({
          filename: file.name || `attachment_${i}`,
          content: new Uint8Array(buffer),
        });
      }

      // Fallback: check for "attachment-info" pattern
      if (attachmentFiles.length === 0) {
        for (const [key, value] of formData.entries()) {
          if (key.startsWith("attachment") && value instanceof File) {
            const buffer = await value.arrayBuffer();
            attachmentFiles.push({
              filename: value.name || key,
              content: new Uint8Array(buffer),
            });
          }
        }
      }
    } else {
      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
    }

    if (!recipient) {
      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
    }

    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
    let jobId: string | null = null;
    let userId: string | null = null;

    const { data: jobMatch } = await supabase
      .from("jobs")
      .select("id, user_id")
      .eq("inbox_email", recipient)
      .single();

    if (jobMatch) {
      jobId = jobMatch.id;
      userId = jobMatch.user_id;
    }

    // Step 2: Fall back to user-level inbox routing
    if (!userId) {
      // Strip +tag for matching: abc+xyz@domain → abc@domain
      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");

      const { data: profile } = await supabase
        .from("profiles")
        .select("user_id, credits, email_enabled, inbox_email")
        .or(`inbox_email.eq.${recipient},inbox_email.eq.${baseRecipient}`)
        .limit(1)
        .single();

      if (!profile) {
        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
      }

      userId = profile.user_id;

      // Check per-user email toggle
      if (!profile.email_enabled) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
      }
    } else {
      // Verify the job owner has email enabled
      const { data: profile } = await supabase
        .from("profiles")
        .select("email_enabled")
        .eq("user_id", userId)
        .single();

      if (profile && !profile.email_enabled) {
        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
      }
    }

    if (attachmentFiles.length === 0) {
      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No attachments" }, { error: "No attachments" });
    }

    // Find or create job if not already matched by per-job routing
    if (!jobId) {
      const { data: activeJob } = await supabase
        .from("jobs")
        .select("id")
        .eq("user_id", userId)
        .eq("status", "pending")
        .order("created_at", { ascending: false })
        .limit(1)
        .single();

      if (activeJob) {
        jobId = activeJob.id;
      } else {
        const { data: newJob } = await supabase
          .from("jobs")
          .insert({
            user_id: userId,
            job_description: "Auto-created from email ingestion",
            status: "pending",
          })
          .select("id")
          .single();
        if (!newJob) throw new Error("Failed to create job");
        jobId = newJob.id;
      }
    }

    // Process attachments
    const resumeIds: string[] = [];
    for (const att of attachmentFiles) {
      const filePath = `${userId}/${jobId}/${Date.now()}_${att.filename}`;
      await supabase.storage.from("resumes").upload(filePath, att.content);

      const { data: resume } = await supabase
        .from("resumes")
        .insert({
          job_id: jobId,
          filename: att.filename,
          file_path: filePath,
          source: "email",
        })
        .select("id")
        .single();

      if (resume) resumeIds.push(resume.id);
    }

    // Send confirmation email to the user (fire-and-forget)
    try {
      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
      const userEmail = authUser?.user?.email;

      if (userEmail) {
        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";

        await supabase.functions.invoke("send-email", {
          body: {
            to: userEmail,
            template_key: "resume_received",
            variables: {
              user_name: userEmail.split("@")[0],
              job_title: jobTitle,
              attachment_count: String(attachmentFiles.length),
              filename: attachmentFiles.map((a) => a.filename).join(", "),
              job_id: jobId || "",
              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
            },
          },
        });
      }
    } catch (emailErr) {
      console.error("Failed to send resume received notification:", emailErr);
      await logSystemError({
        function_name: "email-ingest",
        error_type: "NOTIFICATION_SEND_ERROR",
        severity: "warning",
        error_message: errorToMessage(emailErr),
        error_stack: errorToStack(emailErr),
        user_id: userId,
        job_id: jobId,
      });
    }

    return await logAndRespond(
      200,
      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: attachmentFiles.length, resumes_created: resumeIds.length },
      { success: true, resume_ids: resumeIds, job_id: jobId }
    );
  } catch (err: unknown) {
    console.error("email-ingest error:", err);
    await logSystemError({
      function_name: "email-ingest",
      error_type: "INGEST_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

