 // @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");

    if (!DODO_API_KEY) {
      console.error("DODO_PAYMENTS_API_KEY is not configured");
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "MISSING_CONFIG",
        severity: "critical",
        error_message: "DODO_PAYMENTS_API_KEY is not configured",
      });
      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    }
    if (!WEBHOOK_KEY) {
      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "MISSING_CONFIG",
        severity: "critical",
        error_message: "DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured",
      });
      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    }

    const rawBody = await req.text();
    const webhookHeaders = {
      "webhook-id": req.headers.get("webhook-id") || "",
      "webhook-signature": req.headers.get("webhook-signature") || "",
      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
    };

    const dodo = new DodoPayments({
      bearerToken: DODO_API_KEY,
      webhookKey: WEBHOOK_KEY,
    });

    let unwrapped: any;
    try {
      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
    } catch (e) {
      console.error("Invalid webhook signature", e);
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "WEBHOOK_VALIDATION",
        severity: "critical",
        error_message: errorToMessage(e),
        error_stack: errorToStack(e),
      });
      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
    }

    const eventType: string = unwrapped.type || "unknown";
    const payload: Record<string, unknown> = unwrapped.data || {};

