 54→  const postmarkSig = req.headers.get("x-postmark-signature");
 55→  // Fall back to custom header
 56→  const customSig = req.headers.get("x-webhook-signature");
 57→  const signature = postmarkSig || customSig;
 58→
 59→  if (!signature) {
 60→    // Also allow secret as a query parameter (for simpler webhook providers)
 61→    const url = new URL(req.url);
 62→    const querySecret = url.searchParams.get("secret");
 63→    return querySecret === secret;
 64→  }
 65→
 66→  // Verify HMAC-SHA256 signature
 67→  try {
 68→    const key = await crypto.subtle.importKey(
 69→      "raw",
 70→      new TextEncoder().encode(secret),
 71→      { name: "HMAC", hash: "SHA-256" },
 72→      false,
 73→      ["verify"]
 74→    );
 75→
 76→    const signatureBytes = Uint8Array.from(
 77→      atob(signature),
 78→      (c: string) => c.charCodeAt(0)
 79→    );
 80→
 81→    return await crypto.subtle.verify("HMAC", key, signatureBytes, body);
 82→  } catch (e) {
 83→    console.error("Signature verification failed:", e);
 84→    return false;
 85→  }
 86→}
