 91→  // Only accept POST
 92→  if (req.method !== "POST") {
 93→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 94→      status: 405,
 95→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 96→    });
 97→  }
