 99→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
100→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
101→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
102→
103→  // Helper to log and respond
104→  const logAndRespond = async (
105→    status: number,
106→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
107→    responseBody: Record<string, unknown>
108→  ) => {
109→    try {
110→      await supabase.from("email_ingest_logs").insert({
111→        sender: logData.sender || null,
112→        recipient: logData.recipient || null,
113→        user_id: logData.user_id || null,
114→        job_id: logData.job_id || null,
115→        status: logData.status,
116→        error_message: logData.error_message || null,
117→        attachments_count: logData.attachments_count || 0,
118→        resumes_created: logData.resumes_created || 0,
119→      });
120→    } catch (e) {
121→      console.error("Failed to log email ingest:", e);
122→      await logSystemError({
123→        function_name: "email-ingest",
124→        error_type: "INGEST_LOG_ERROR",
125→        severity: "warning",
126→        error_message: errorToMessage(e),
127→        error_stack: errorToStack(e),
128→        user_id: logData.user_id || null,
129→        job_id: logData.job_id || null,
130→      });
131→    }
132→    return new Response(JSON.stringify(responseBody), {
133→      status,
134→      headers: { ...corsHeaders, "Content-Type": "application/json" },
135→    });
136→  };
137→
138→  try {
139→    // --- [C1 FIX] Verify webhook signature before processing ---
140→    const rawBody = await req.clone().arrayBuffer();
141→    const isValid = await verifyWebhookSignature(req, rawBody);
142→    if (!isValid) {
143→      return await logAndRespond(
144→        401,
145→        { status: "rejected", error_message: "Invalid or missing webhook signature" },
146→        { error: "Unauthorized" }
147→      );
148→    }
149→
150→    // Check global email ingestion toggle
151→    const { data: config } = await supabase
152→      .from("platform_config")
153→      .select("email_ingestion_enabled, max_file_size_mb, max_resumes_per_job")
154→      .limit(1)
155→      .single();
156→
157→    if (config && !config.email_ingestion_enabled) {
158→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
159→    }
160→
161→    const maxFileSizeBytes = (config?.max_file_size_mb || 10) * 1024 * 1024;
162→    const maxResumesPerJob = config?.max_resumes_per_job || 50;
163→
164→    // Parse incoming payload — support Postmark JSON, legacy JSON, and multipart/form-data
165→    let sender: string | null = null;
166→    let recipient: string | null = null;
167→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
168→
169→    const contentType = req.headers.get("content-type") || "";
170→
171→    if (contentType.includes("application/json")) {
172→      const body = await req.json();
173→
174→      // Postmark inbound webhook format
175→      if (body.FromFull || body.ToFull || body.Attachments) {
176→        // Postmark format
177→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
178→
179→        // ToFull is an array in Postmark
180→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
181→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
182→        } else if (body.To) {
183→          recipient = extractEmail(body.To);
184→        }
185→
186→        // Postmark attachments: array of { Name, Content (base64), ContentType, ContentLength }
187→        if (body.Attachments && Array.isArray(body.Attachments)) {
188→          let count = 0;
189→          for (const att of body.Attachments) {
190→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
191→            if (!att.Name || !att.Content) continue;
192→            // [M2 FIX] Only accept PDF and DOCX
193→            if (!hasAllowedExtension(att.Name)) continue;
194→            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
195→            // [H2 FIX] Enforce file size limit
196→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
197→            attachmentFiles.push({ filename: att.Name, content: fileContent });
198→            count++;
199→          }
200→        }
201→      } else {
202→        // Legacy JSON format (backward compatible)
203→        sender = body.sender || null;
204→        recipient = body.recipient || null;
205→
206→        if (body.attachments && Array.isArray(body.attachments)) {
207→          let count = 0;
208→          for (const att of body.attachments) {
209→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
210→            if (!att.filename || !att.content) continue;
211→            // [M2 FIX] Enforce file type filter on legacy format too
212→            if (!hasAllowedExtension(att.filename)) continue;
213→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
214→            // [H2 FIX] Enforce file size limit
215→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
216→            attachmentFiles.push({ filename: att.filename, content: fileContent });
217→            count++;
218→          }
219→        }
220→      }
221→    } else if (contentType.includes("multipart/form-data")) {
222→      // SendGrid/Mailgun multipart format (backward compatible)
223→      const formData = await req.formData();
224→
225→      const envelope = formData.get("envelope") as string | null;
226→      const fromField = formData.get("from") as string | null;
227→      const toField = formData.get("to") as string | null;
228→
229→      // Parse sender
230→      if (envelope) {
231→        try {
232→          const env = JSON.parse(envelope);
233→          if (env.from) sender = extractEmail(env.from);
234→        } catch { /* ignore */ }
235→      }
236→      if (!sender && fromField) sender = extractEmail(fromField);
237→
238→      // Parse recipient
239→      if (envelope) {
240→        try {
241→          const env = JSON.parse(envelope);
242→          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
243→        } catch { /* ignore */ }
244→      }
245→      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);
246→
247→      // [M1 FIX] Extract attachments with capped iteration count
248→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
249→      const maxIter = Math.min(Math.max(attachmentCount, 10), MAX_ATTACHMENTS_PER_EMAIL);
250→      let filesCollected = 0;
251→      for (let i = 1; i <= maxIter && filesCollected < MAX_ATTACHMENTS_PER_EMAIL; i++) {
252→        const file = formData.get(`attachment${i}`) as File | null;
253→        if (!file) continue;
254→        // [M2 FIX] Enforce file type filter on multipart format
255→        const filename = file.name || `attachment_${i}`;
256→        if (!hasAllowedExtension(filename)) continue;
257→        const buffer = await file.arrayBuffer();
258→        // [H2 FIX] Enforce file size limit
259→        if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
260→        attachmentFiles.push({
261→          filename,
262→          content: new Uint8Array(buffer),
263→        });
264→        filesCollected++;
265→      }
266→
267→      // Fallback: check for "attachment-info" pattern
268→      if (attachmentFiles.length === 0) {
269→        for (const [key, value] of formData.entries()) {
270→          if (filesCollected >= MAX_ATTACHMENTS_PER_EMAIL) break;
271→          if (key.startsWith("attachment") && value instanceof File) {
272→            const filename = value.name || key;
273→            // [M2 FIX] Enforce file type filter
274→            if (!hasAllowedExtension(filename)) continue;
275→            const buffer = await value.arrayBuffer();
276→            // [H2 FIX] Enforce file size limit
277→            if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
278→            attachmentFiles.push({
279→              filename,
280→              content: new Uint8Array(buffer),
281→            });
282→            filesCollected++;
283→          }
284→        }
285→      }
286→    } else {
287→      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
288→    }
289→
290→    if (!recipient) {
291→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
292→    }
293→
294→    // [L3 FIX] Validate recipient is a properly formatted email
295→    if (!isValidEmail(recipient)) {
296→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "Invalid recipient format" }, { error: "Invalid recipient" });
297→    }
298→
299→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
300→    let jobId: string | null = null;
301→    let userId: string | null = null;
302→
303→    const { data: jobMatch } = await supabase
304→      .from("jobs")
305→      .select("id, user_id")
