318→
319→      // [C2 FIX] Use separate parameterized .eq() queries instead of .or() with string interpolation
320→      let profile: { user_id: string; credits: number; email_enabled: boolean; inbox_email: string } | null = null;
321→
322→      const { data: exactMatch } = await supabase
323→        .from("profiles")
324→        .select("user_id, credits, email_enabled, inbox_email")
325→        .eq("inbox_email", recipient)
326→        .limit(1)
327→        .single();
328→
329→      if (exactMatch) {
330→        profile = exactMatch;
331→      } else if (baseRecipient !== recipient) {
332→        const { data: baseMatch } = await supabase
333→          .from("profiles")
334→          .select("user_id, credits, email_enabled, inbox_email")
335→          .eq("inbox_email", baseRecipient)
336→          .limit(1)
337→          .single();
338→        profile = baseMatch;
339→      }
340→
341→      if (!profile) {
342→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
343→      }
344→
345→      userId = profile.user_id;
346→
347→      // Check per-user email toggle
348→      if (!profile.email_enabled) {
349→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
350→      }
351→
352→      // [H3 FIX] Check that user has credits before accepting resumes
353→      if (profile.credits <= 0) {
