361→        .eq("user_id", userId)
362→        .single();
363→
364→      if (profile && !profile.email_enabled) {
365→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
366→      }
367→
368→      // [H3 FIX] Check credits for job-routed emails too
369→      if (profile && profile.credits <= 0) {
370→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
371→      }
372→    }
373→
374→    if (attachmentFiles.length === 0) {
375→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No valid attachments (only .pdf and .docx accepted)" }, { error: "No valid attachments" });
376→    }
377→
378→    // Find or create job if not already matched by per-job routing
379→    if (!jobId) {
