393→        const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
394→        const { count: recentAutoJobs } = await supabase
395→          .from("jobs")
396→          .select("id", { count: "exact", head: true })
397→          .eq("user_id", userId)
398→          .eq("job_description", "Auto-created from email ingestion")
399→          .gte("created_at", oneDayAgo);
400→
401→        if ((recentAutoJobs || 0) >= 5) {
402→          return await logAndRespond(429, { sender, recipient, user_id: userId, status: "rejected", error_message: "Too many auto-created jobs" }, { error: "Rate limit exceeded" });
403→        }
404→
405→        const { data: newJob } = await supabase
406→          .from("jobs")
407→          .insert({
408→            user_id: userId,
409→            job_description: "Auto-created from email ingestion",
410→            status: "pending",
411→          })
412→          .select("id")
413→          .single();
414→        if (!newJob) throw new Error("Failed to create job");
415→        jobId = newJob.id;
416→      }
417→    }
418→
419→    // [H3 FIX] Check existing resume count for the job before uploading
420→    const { count: existingResumeCount } = await supabase
421→      .from("resumes")
422→      .select("id", { count: "exact", head: true })
423→      .eq("job_id", jobId);
424→
425→    const remainingSlots = maxResumesPerJob - (existingResumeCount || 0);
426→    if (remainingSlots <= 0) {
427→      return await logAndRespond(429, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Job has reached maximum resume limit" }, { error: "Resume limit reached for this job" });
428→    }
429→
430→    // Process attachments (limited to remaining slots)
431→    const resumeIds: string[] = [];
432→    const filesToProcess = attachmentFiles.slice(0, remainingSlots);
433→
434→    for (const att of filesToProcess) {
435→      // [M4 FIX] Sanitize filename to prevent path traversal or injection
436→      const safeName = sanitizeFilename(att.filename);
437→      const filePath = `${userId}/${jobId}/${Date.now()}_${safeName}`;
