439→
440→      const { data: resume } = await supabase
441→        .from("resumes")
442→        .insert({
443→          job_id: jobId,
444→          filename: safeName,
445→          file_path: filePath,
446→          source: "email",
447→        })
448→        .select("id")
449→        .single();
450→
451→      if (resume) resumeIds.push(resume.id);
452→    }
453→
454→    // Send confirmation email to the user (fire-and-forget)
455→    try {
456→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
457→      const userEmail = authUser?.user?.email;
458→
459→      if (userEmail) {
460→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
461→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
462→
463→        await supabase.functions.invoke("send-email", {
