480→      await logSystemError({
481→        function_name: "email-ingest",
482→        error_type: "NOTIFICATION_SEND_ERROR",
483→        severity: "warning",
484→        error_message: errorToMessage(emailErr),
485→        error_stack: errorToStack(emailErr),
486→        user_id: userId,
487→        job_id: jobId,
488→      });
489→    }
490→
491→    return await logAndRespond(
492→      200,
493→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: filesToProcess.length, resumes_created: resumeIds.length },
494→      { success: true, resume_ids: resumeIds, job_id: jobId }
